import{_ as d,o as e,c as o,a2 as r}from"./chunks/framework.Dx-TCpNt.js";const u=JSON.parse('{"title":"キーボードショートカット","description":"すべてのキーとマウスジェスチャーを1ページにまとめました。テキストフィールドにフォーカスがある間は単キーのショートカットは無視されるため、ノート入力の途中で表示が切り替わることはありません。","frontmatter":{"description":"すべてのキーとマウスジェスチャーを1ページにまとめました。テキストフィールドにフォーカスがある間は単キーのショートカットは無視されるため、ノート入力の途中で表示が切り替わることはありません。"},"headers":[],"relativePath":"ja/guide/shortcuts.md","filePath":"ja/guide/shortcuts.md","lastUpdated":1794883223000}'),a={name:"ja/guide/shortcuts.md"};function c(l,t,i,h,n,s){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="キーボードショートカット" tabindex="-1">キーボードショートカット <a class="header-anchor" href="#キーボードショートカット" aria-label="Permalink to &quot;キーボードショートカット&quot;">​</a></h1><p>すべてのキーとマウスジェスチャーを1ページにまとめました。テキストフィールドにフォーカスがある間は単キーのショートカットは無視されるため、ノート入力の途中で表示が切り替わることはありません。</p><h2 id="このページで解決すること" tabindex="-1">このページで解決すること <a class="header-anchor" href="#このページで解決すること" aria-label="Permalink to &quot;このページで解決すること&quot;">​</a></h2><p>ショートカットはライブラリ、ワークベンチ、比較リーダー、ノートエディタに分散しています。各章を探し回る代わりに、操作を覚える間はこのページを手元に置くか、印刷してモニターの横に貼ってください。</p><h2 id="全体" tabindex="-1">全体 <a class="header-anchor" href="#全体" aria-label="Permalink to &quot;全体&quot;">​</a></h2><table tabindex="0"><thead><tr><th>キー</th><th>動作</th></tr></thead><tbody><tr><td><code>[</code></td><td>前のページ（話の境界を越えます）。</td></tr><tr><td><code>]</code></td><td>次のページ（話の境界を越えます）。</td></tr><tr><td><code>←</code> / <code>→</code></td><td>閲覧方向に沿って前 / 次のページへ。縦読みでは <code>↑</code> / <code>↓</code>。</td></tr><tr><td><code>P</code></td><td>コマ分割ワークベンチに切り替え。</td></tr><tr><td><code>C</code></td><td>比較リーダーに切り替え。</td></tr><tr><td><code>O</code></td><td>原版ビューに切り替え。</td></tr><tr><td><code>S</code></td><td>ライブラリサイドバーの表示 / 非表示。</td></tr><tr><td><code>N</code></td><td>ノート列の表示 / 非表示。</td></tr><tr><td><code>E</code></td><td>エクスポートダイアログを開く（ページを開いている場合）。</td></tr><tr><td><code>R</code></td><td>集中モードに入る / 出る。</td></tr><tr><td><code>Esc</code></td><td>集中モードを終了する（ダイアログが開いていないとき）。</td></tr><tr><td><code>?</code></td><td>キーボードと操作のヘルプを開く。</td></tr><tr><td><code>Ctrl+Z</code></td><td>最後のコマの変更を元に戻す。</td></tr><tr><td><code>Ctrl+Shift+Z</code></td><td>やり直す。</td></tr><tr><td><code>Ctrl+Y</code></td><td>やり直す（代替）。</td></tr></tbody></table><p>閲覧モードでは編集系のショートカット（<code>Ctrl+Z</code>、<code>Ctrl+Y</code>、保存、コマや注釈のキー）は無効です。ページ送りと表示の切り替えはそのまま使えます。</p><h2 id="集中モード" tabindex="-1">集中モード <a class="header-anchor" href="#集中モード" aria-label="Permalink to &quot;集中モード&quot;">​</a></h2><p><code>R</code> を押すか、上部バーの <code>⛶</code> をクリックすると入ります。上部バー、ステージのツールバー、コマのセクションレール、ステータスバーが畳まれ、ページが画面いっぱいに広がりますが、編集 / 閲覧モードは変わりません。<code>Esc</code>（ダイアログが開いていないとき）または <code>R</code> で戻り、タッチ端末では空白部分のダブルタップでも終了します。状態は記憶され、次回も維持されます。入ったときに終了方法を短く表示し、その後フェードアウトして絵を覆い続けることはありません。</p><h2 id="ファイル" tabindex="-1">ファイル <a class="header-anchor" href="#ファイル" aria-label="Permalink to &quot;ファイル&quot;">​</a></h2><table tabindex="0"><thead><tr><th>キー</th><th>動作</th></tr></thead><tbody><tr><td><code>Ctrl+O</code></td><td>プロジェクトファイル（<code>.mnproj</code>）を開く。</td></tr><tr><td><code>Ctrl+S</code></td><td>現在のページを保存。</td></tr><tr><td><code>Ctrl+Shift+S</code></td><td>プロジェクトファイルへ保存——ライブラリ全体を開いている <code>.mnproj</code> に書き戻します。</td></tr></tbody></table><p>これらのファイルショートカットは、入力中でも動作し、デスクトップアプリと同じように振る舞います。読み取り専用モードや、プロジェクトがリンクされていない場合は、書き込まずに理由を表示して保存を拒否します。</p><p><strong>ファイル → 名前を付けて保存…</strong> にショートカットはありません。保存先を毎回尋ねる操作なので、明示的に選ぶメニュー項目のままにしています。</p><h2 id="コマ分割ワークベンチ" tabindex="-1">コマ分割ワークベンチ <a class="header-anchor" href="#コマ分割ワークベンチ" aria-label="Permalink to &quot;コマ分割ワークベンチ&quot;">​</a></h2><table tabindex="0"><thead><tr><th>キー / ジェスチャー</th><th>動作</th></tr></thead><tbody><tr><td>枠をドラッグ</td><td>コマを移動。</td></tr><tr><td>角または辺のハンドルをドラッグ</td><td>8方向にリサイズ。</td></tr><tr><td>空白をダブルクリック</td><td>既定のコマを追加。</td></tr><tr><td>空白の上をドラッグ</td><td>コマを描く。</td></tr><tr><td><code>Shift</code> + ドラッグ</td><td>新しいコマを正方形に固定。</td></tr><tr><td><code>Alt</code> + ドラッグ</td><td>吸着を無効にする。</td></tr><tr><td><code>Ctrl</code> クリック / <code>Shift</code> クリック</td><td>選択にコマを追加、または選択から外す。</td></tr><tr><td>矢印キー</td><td>選択範囲をページの0.2%だけ移動。</td></tr><tr><td><code>Shift</code> + 矢印キー</td><td>1%移動。</td></tr><tr><td><code>Delete</code> / <code>Backspace</code></td><td>選択したコマ（または選択した注釈）を削除。</td></tr><tr><td><code>Enter</code></td><td>保存（確認モード）。</td></tr><tr><td><code>Esc</code></td><td>変更を破棄（確認モード）。それ以外では注釈ツールを終了するか、マークの選択を解除。</td></tr></tbody></table><p>注釈ツールバーには英字のショートカットはなく、マウスのみです。<code>Esc</code> は常に1段階戻ります。選択中の注釈 → 現在のツール → 未保存のページ、の順です。</p><h2 id="比較リーダー" tabindex="-1">比較リーダー <a class="header-anchor" href="#比較リーダー" aria-label="Permalink to &quot;比較リーダー&quot;">​</a></h2><table tabindex="0"><thead><tr><th>キー / ジェスチャー</th><th>動作</th></tr></thead><tbody><tr><td><code>H</code></td><td>すべてマスク（マスクの全体切り替えをオン）。</td></tr><tr><td><code>Shift+H</code></td><td>すべて表示（マスクの全体切り替えをオフ）。</td></tr><tr><td>ペインをドラッグ</td><td>その言語をパン。</td></tr><tr><td>ペイン上でホイール</td><td>その言語を拡大縮小。</td></tr><tr><td><code>Alt</code> + ドラッグ / ホイール</td><td>現在のコマだけにジェスチャーを適用。</td></tr><tr><td>マスク中のペインをクリック</td><td>一時的に表示。もう一度クリックするとマスク。</td></tr></tbody></table><p>コマの移動には <strong>前のコマ</strong> / <strong>次のコマ</strong> ボタンを使います。<code>[</code> と <code>]</code> がすでにページ移動に使われているため、キーには割り当てられていません。</p><h2 id="ノートエディター" tabindex="-1">ノートエディター <a class="header-anchor" href="#ノートエディター" aria-label="Permalink to &quot;ノートエディター&quot;">​</a></h2><table tabindex="0"><thead><tr><th>キー</th><th>動作</th></tr></thead><tbody><tr><td><code>Ctrl+B</code></td><td>太字。</td></tr><tr><td><code>Ctrl+I</code></td><td>斜体。</td></tr><tr><td><code>Ctrl+K</code></td><td>リンクを挿入。</td></tr><tr><td><code>Ctrl+Enter</code></td><td>ノートを保存（または一時メモを保存）。</td></tr><tr><td>タグ欄で <code>Enter</code></td><td>タグを追加。</td></tr><tr><td><code>Tab</code></td><td>エディター内でインデント。</td></tr></tbody></table><h2 id="マウスのみの操作" tabindex="-1">マウスのみの操作 <a class="header-anchor" href="#マウスのみの操作" aria-label="Permalink to &quot;マウスのみの操作&quot;">​</a></h2><p>一部のコントロールには、仕様上キーボードの代替がありません。</p><ul><li>ペインの区切りとコマ詳細ビューの分割線：ドラッグでサイズ変更、分割線はフォーカス時に方向キーでも移動できます。</li><li>比較リーダーの言語チップの並べ替え：チップをドラッグ。</li><li>ズームボタン：コマのツールバーの <code>−</code> / <code>＋</code>。</li><li>コマテンプレートと位置合わせプリセットの選択。</li><li>右クリックメニュー：注釈、比較ペイン、詳細ビューのコマ。ペインメニューには拡大表示、マスク、単一コマ PNG、コマ番号、リンクがあります。</li><li>コマ詳細ビューで絵をドラッグして位置合わせする操作と <strong>同期移動</strong> スイッチ。</li><li>保存インジケーターをクリックして書き戻しパネルを開く操作。</li></ul><h2 id="よくある落とし穴" tabindex="-1">よくある落とし穴 <a class="header-anchor" href="#よくある落とし穴" aria-label="Permalink to &quot;よくある落とし穴&quot;">​</a></h2><ul><li><strong>ショートカットが文字を入力してしまう。</strong> フォーカスが input、textarea、contenteditable 要素にあります。先にステージをクリックしてください。</li><li><strong><code>H</code> でマスクされない。</strong> フォーカスがノートやツールバーのフィールドにあります。入力中は比較のショートカットは無視されます。</li><li><strong><code>E</code> が何もしない。</strong> ページを開いていないため、エクスポートダイアログは使えません。</li><li><strong><code>Ctrl+Z</code> でノートが元に戻ってしまう。</strong> テキストフィールド内ではブラウザ標準の元に戻すが働きます。ページ単位の元に戻す操作はステージ上でのみ機能します。</li></ul><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/KomaYomi-docs/ja/guide/panels">コマ分割ワークベンチ</a> — これらのキーが操作するコントロール。</li><li><a href="/KomaYomi-docs/ja/guide/compare">比較リーダー</a> — マスクと位置合わせ。</li><li><a href="/KomaYomi-docs/ja/guide/notes">ノート</a> — エディターの動作。</li></ul>',28)])])}const p=d(a,[["render",c]]);export{u as __pageData,p as default};
